package com.meetspace.controller; import com.meetspace.dto.*; import com.meetspace.dto.BookingDtos.*; import com.meetspace.security.UserPrincipal; import com.meetspace.service.BookingService; import jakarta.validation.Valid; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController public class BookingController{private final BookingService s;public BookingController(BookingService s){this.s=s;}@PostMapping("/api/bookings") ApiResponse<Response> create(@AuthenticationPrincipal UserPrincipal p,@Valid @RequestBody Create x){return ApiResponse.ok("Booking created",s.create(p.id(),x));}@PostMapping("/api/bookings/{bookingId}/cancel") ApiResponse<Response> cancel(@AuthenticationPrincipal UserPrincipal p,@PathVariable UUID bookingId){return ApiResponse.ok("Booking cancelled",s.cancel(p.id(),bookingId));}@GetMapping("/api/bookings") ApiResponse<List<Response>> mine(@AuthenticationPrincipal UserPrincipal p){return ApiResponse.ok("Bookings retrieved",s.mine(p.id()));}@GetMapping("/api/rooms/availability") ApiResponse<Availability> available(@RequestParam UUID roomId,@RequestParam LocalDate date,@RequestParam LocalTime startTime,@RequestParam LocalTime endTime){return ApiResponse.ok("Availability checked",s.availability(roomId,date,startTime,endTime));}}